<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$me=require_login();$shops=mp550_user_shops((int)$me['id']);if(!$shops){mp550_public_header('Seller Center');echo '<section class="mp550-empty seller-empty"><b>No seller shop assigned</b><span>Ask an administrator to create/assign a marketplace shop or POS role to your account.</span><a class="mp550-btn" href="/shop.php">Back to marketplace</a></section>';mp550_public_footer();exit;}$shopId=(int)($_GET['shop']??$shops[0]['id']);$allowed=array_column($shops,'id');if(!in_array($shopId,array_map('intval',$allowed),true))$shopId=(int)$shops[0]['id'];$shop=mp550_shop($shopId);$flash='';$err='';if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();try{$action=(string)($_POST['action']??'');if($action==='order_status'){mp550_update_order_status((int)$_POST['order_id'],(string)$_POST['status'],(int)$me['id'],(string)($_POST['note']??''));$flash='Order updated.';}elseif($action==='payout'){mp550_request_payout('seller',(int)$me['id'],(float)$_POST['amount'],$shopId,(string)$_POST['method'],(string)$_POST['account_title'],(string)$_POST['account_reference']);$flash='Seller payout request submitted.';}}catch(Throwable $e){$err=$e->getMessage();}}$stats=mp550_stats((int)$me['id'],$shopId);$orders=mp550_orders(['shop'=>$shopId],100);$products=mp550_products(['shop'=>$shopId],100);$auctions=mp550_auctions(['shop'=>$shopId],30);mp550_public_header('Seller Center');
?>
<section class="mp550-seller-hero"><div><span>SELLER COMMAND CENTER</span><h1><?=e($shop['name'])?></h1><p>Orders, products, payouts, POS and auctions from one seller workspace.</p></div><select onchange="location='?shop='+this.value"><?php foreach($shops as $s):?><option value="<?=(int)$s['id']?>" <?=$shopId===(int)$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></section><?php if($flash):?><div class="mp550-alert ok"><?=e($flash)?></div><?php endif;?><?php if($err):?><div class="mp550-alert err"><?=e($err)?></div><?php endif;?><section class="seller-kpis"><div><span>Orders</span><b><?=e((string)($stats['orders']??0))?></b></div><div><span>Open orders</span><b><?=e((string)($stats['open_orders']??0))?></b></div><div><span>Gross sales</span><b><?=mp550_money((float)($stats['gross']??0))?></b></div><div><span>Platform commission</span><b><?=mp550_money((float)($stats['commission']??0))?></b></div><div><span>Seller net</span><b><?=mp550_money((float)($stats['seller_net']??0))?></b></div></section><section class="seller-grid"><div class="panel"><div class="section-head"><div><span>ORDER MANAGEMENT</span><h2>Incoming orders</h2></div></div><?php foreach($orders as $o):?><article class="seller-order"><div><b><?=e($o['order_number'])?></b><span><?=e($o['customer_name'])?> · <?=e($o['customer_phone'])?></span><small><?=e(date('d M · h:i A',strtotime($o['placed_at'])))?> · <?=mp550_money((float)$o['grand_total'])?></small></div><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="order_status"><input type="hidden" name="order_id" value="<?=(int)$o['id']?>"><select name="status"><option><?=e($o['status'])?></option><?php foreach(['confirmed','processing','ready','shipped','delivered','completed','cancelled'] as $st):?><option value="<?=$st?>"><?=ucfirst($st)?></option><?php endforeach;?></select><button>Update</button></form></article><?php endforeach;?><?php if(!$orders):?><div class="mp550-empty"><span>No orders for this shop yet.</span></div><?php endif;?></div><aside><div class="panel"><div class="section-head"><div><span>CATALOG</span><h2><?=count($products)?> products</h2></div></div><?php foreach(array_slice($products,0,8) as $p):?><div class="mini-product"><span><?=e($p['title'])?></span><b><?=mp550_money((float)$p['sale_price'])?></b><em><?=e((string)$p['stock'])?> stock</em></div><?php endforeach;?><a class="mp550-btn ghost wide" href="/shop.php?shop=<?=$shopId?>">Open storefront</a></div><div class="panel"><h2>Seller payout</h2><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="payout"><label>Amount<input type="number" name="amount" min="1" required></label><label>Method<select name="method"><option>Bank Transfer</option><option>JazzCash</option><option>EasyPaisa</option></select></label><label>Account title<input name="account_title" required></label><label>Account reference<input name="account_reference" required></label><button class="mp550-btn wide">Request payout</button></form></div><div class="panel"><h2>Auction activity</h2><?php foreach($auctions as $a):?><a class="mini-row" href="/auction.php?id=<?=(int)$a['id']?>"><span><?=e($a['title'])?></span><b><?=mp550_money((float)$a['current_price'])?></b></a><?php endforeach;?></div></aside></section>
<?php mp550_public_footer(); ?>
